import json, sys
errors = []
for line in sys.stdin:
    e = json.loads(line.strip())
    errors.append(e)
# Group by sub-type
subtypes = {}
for e in errors:
    err = e.get('error', '')
    key = err.split(': ', 1)[1] if ': ' in err else err
    if key not in subtypes:
        subtypes[key] = []
    subtypes[key].append({'critique': e.get('critique', '')[:120], 'context': e.get('context', '')})
for k, v in sorted(subtypes.items(), key=lambda x: -len(x[1])):
    print(f'\n=== {k} ({len(v)}x) ===')
    for item in v:
        print(f'  {item[\"context\"]}: {item[\"critique\"]}')
" 2>/dev/null || cat agents/optimizer/ERROR_LOG.jsonl | grep "FM-3.1"

